'use strict';
// Minimal hand-authored 3x5 pixel bitmap font, only the glyphs the battle
// mockup needs. Proof-of-concept only -- production should use a licensed
// pixel font (see PIXEL_ART_DIRECTION.md section on UI typography).
const GLYPHS = {
  F: ['111', '100', '110', '100', '100'],
  E: ['111', '100', '110', '100', '111'],
  R: ['110', '101', '110', '101', '101'],
  O: ['111', '101', '101', '101', '111'],
  L: ['100', '100', '100', '100', '111'],
  I: ['111', '010', '010', '010', '111'],
  M: ['101', '111', '111', '101', '101'],
  A: ['010', '101', '111', '101', '101'],
  Q: ['111', '101', '101', '111', '001'],
  U: ['101', '101', '101', '101', '111'],
  B: ['110', '101', '110', '101', '110'],
  T: ['111', '010', '010', '010', '010'],
  H: ['101', '101', '111', '101', '101'],
  P: ['110', '101', '110', '100', '100'],
  V: ['101', '101', '101', '101', '010'],
  G: ['111', '100', '111', '101', '111'],
  N: ['101', '111', '111', '101', '101'],
  D: ['110', '101', '101', '101', '110'],
  W: ['101', '101', '101', '111', '101'],
  K: ['101', '101', '110', '101', '101'],
  C: ['011', '100', '100', '100', '011'],
  S: ['011', '100', '010', '001', '110'],
  J: ['001', '001', '001', '101', '010'],
  X: ['101', '101', '010', '101', '101'],
  Y: ['101', '101', '010', '010', '010'],
  Z: ['111', '001', '010', '100', '111'],
  '?': ['111', '001', '010', '000', '010'],
  '-': ['000', '000', '111', '000', '000'],
  ':': ['000', '010', '000', '010', '000'],
  '%': ['101', '001', '010', '100', '101'],
  '!': ['010', '010', '010', '000', '010'],
  '0': ['111', '101', '101', '101', '111'],
  '1': ['010', '110', '010', '010', '111'],
  '2': ['111', '001', '111', '100', '111'],
  '3': ['111', '001', '111', '001', '111'],
  '4': ['101', '101', '111', '001', '001'],
  '5': ['111', '100', '111', '001', '111'],
  '6': ['111', '100', '111', '101', '111'],
  '7': ['111', '001', '001', '001', '001'],
  '8': ['111', '101', '111', '101', '111'],
  '9': ['111', '101', '111', '001', '111'],
  '/': ['001', '001', '010', '100', '100'],
  ' ': ['000', '000', '000', '000', '000'],
};

function drawText(c, text, x, y, color) {
  let cx = x;
  for (const ch of text.toUpperCase()) {
    const glyph = GLYPHS[ch] || GLYPHS[' '];
    for (let row = 0; row < 5; row++) {
      for (let col = 0; col < 3; col++) {
        if (glyph[row][col] === '1') c.setPixel(cx + col, y + row, color);
      }
    }
    cx += 4; // 3px glyph + 1px spacing
  }
  return cx;
}

module.exports = { drawText, GLYPHS };
